node -e "
const c=require('crypto');
const target='6e88be8bad7eae9d9e10aa061224034f';
for (const it of [1,2,10,100,400,1000,2000,4096,10000,65536]) {
  for (const h of ['sha1','sha256','sha512']) {
    const r=c.pbkdf2Sync('password','salt',it,16,h).toString('hex');
    if(r===target) console.log('MATCH', it, h);
  }
}
console.log('done');
"
